  1	package com.marealta;
  2	
  3	import com.marealta.api.ApiController;
  4	import com.marealta.api.JsonMapper;
  5	import com.marealta.infrastructure.database.Database;
  6	import com.marealta.infrastructure.database.ReservationRepository;
  7	import com.marealta.infrastructure.database.RoomRepository;
  8	import com.marealta.infrastructure.messaging.MessageRepository;
  9	import io.javalin.Javalin;
 10	import io.javalin.json.JavalinJackson;
 11	
 12	public class App {
 13	    public static void main(String[] args) {
 14	        try {
 15	            String dbUrl = System.getenv("DB_URL");
 16	            String dbUser = System.getenv("DB_USER");
 17	            String dbPassword = System.getenv("DB_PASSWORD");
 18	            String portEnv = System.getenv("PORT");
 19	            int port = portEnv != null ? Integer.parseInt(portEnv) : 7070;
 20	
 21	            if (dbUrl == null || dbUser == null || dbPassword == null) {
 22	                throw new IllegalStateException("Database configuration missing. Please set DB_URL, DB_USER, and DB_PASSWORD environment variables.");
 23	            }
 24	
 25	            Database database = new Database(dbUrl, dbUser, dbPassword);
 26	
 27	            RoomRepository roomRepository = new RoomRepository(database.getConnection());
 28	            ReservationRepository reservationRepository = new ReservationRepository(database.getConnection());
 29	            MessageRepository messageRepository = new MessageRepository(database.getConnection());
 30	
 31	            roomRepository.initializeRooms();
 32	
 33	            ApiController apiController = new ApiController(roomRepository, reservationRepository, messageRepository);
 34	
 35	            Javalin app = Javalin.create(config -> {
 36	                config.jsonMapper(new JavalinJackson(JsonMapper.get(), true));
 37	            }).start(port);
 38	
 39	            apiController.registerRoutes(app);
 40	
 41	            System.out.println("Pousada Maré Alta API started on port " + port);
 42	
 43	            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 44	                try {
 45	                    app.stop();
 46	                    database.close();
 47	                } catch (Exception e) {
 48	                    e.printStackTrace();
 49	                }
 50	            }));
 51	
 52	        } catch (Exception e) {
 53	            e.printStackTrace();
 54	            System.exit(1);
 55	        }
 56	    }
 57	}
 58	package com.marealta.api;
 59	
 60	import com.fasterxml.jackson.databind.ObjectMapper;
 61	import com.marealta.api.dto.CreateReservationRequest;
 62	import com.marealta.api.dto.ErrorResponse;
 63	import com.marealta.domain.model.*;
 64	import com.marealta.domain.service.*;
 65	import com.marealta.infrastructure.database.ReservationRepository;
 66	import com.marealta.infrastructure.database.RoomRepository;
 67	import com.marealta.infrastructure.messaging.MessageRepository;
 68	import io.javalin.Javalin;
 69	import io.javalin.http.Context;
 70	
 71	import java.math.BigDecimal;
 72	import java.time.LocalDate;
 73	import java.time.YearMonth;
 74	import java.util.HashMap;
 75	import java.util.List;
 76	import java.util.Map;
 77	
 78	public class ApiController {
 79	    private final RoomRepository roomRepository;
 80	    private final ReservationRepository reservationRepository;
 81	    private final MessageRepository messageRepository;
 82	    private final PricingService pricingService;
 83	    private final DocumentService documentService;
 84	    private final EmailService emailService;
 85	    private final ReportService reportService;
 86	    private final ValidationService validationService;
 87	    private final ObjectMapper objectMapper;
 88	
 89	    public ApiController(
 90	        RoomRepository roomRepository,
 91	        ReservationRepository reservationRepository,
 92	        MessageRepository messageRepository
 93	    ) {
 94	        this.roomRepository = roomRepository;
 95	        this.reservationRepository = reservationRepository;
 96	        this.messageRepository = messageRepository;
 97	        this.pricingService = new PricingService();
 98	        this.documentService = new DocumentService();
 99	        this.emailService = new EmailService(messageRepository);
100	        this.reportService = new ReportService();
101	        this.validationService = new ValidationService();
102	        this.objectMapper = JsonMapper.get();
103	    }
104	
105	    public void registerRoutes(Javalin app) {
106	        app.get("/rooms", this::getRooms);
107	        app.post("/reservations", this::createReservation);
108	        app.get("/reservations/{id}", this::getReservation);
109	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
110	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
111	        app.post("/reservations/{id}/check-in", this::checkInReservation);
112	        app.post("/reservations/{id}/check-out", this::checkOutReservation);
113	        app.get("/reservations/{id}/document", this::getDocument);
114	        app.get("/messages", this::getMessages);
115	        app.get("/reports/occupancy", this::getOccupancyReport);
116	        app.get("/reports/revenue", this::getRevenueReport);
117	
118	        app.exception(ValidationService.ValidationException.class, (e, ctx) -> {
119	            int status = switch (e.getErrorCode()) {
120	                case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
121	                case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
122	                case "CAPACITY_EXCEEDED" -> 422;
123	                default -> 400;
124	            };
125	            ctx.status(status).json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
126	        });
127	
128	        app.exception(IllegalStateException.class, (e, ctx) -> {
129	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
130	        });
131	
132	        app.exception(Exception.class, (e, ctx) -> {
133	            e.printStackTrace();
134	            ctx.status(500).json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
135	        });
136	    }
137	
138	    private void getRooms(Context ctx) throws Exception {
139	        List<Room> rooms = roomRepository.findAll();
140	        List<Map<String, Object>> response = rooms.stream()
141	            .<Map<String, Object>>map(room -> Map.of(
142	                "number", room.number(),
143	                "type", room.type().toString(),
144	                "capacity", room.capacity(),
145	                "nightlyRate", room.nightlyRate()
146	            ))
147	            .toList();
148	        ctx.json(response);
149	    }
150	
151	    private void createReservation(Context ctx) throws Exception {
152	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
153	        validationService.validateCreateReservation(request);
154	
155	        Room room = roomRepository.findByNumber(request.roomNumber())
156	            .orElseThrow(() -> new ValidationService.ValidationException("ROOM_NOT_FOUND",
157	                "Room " + request.roomNumber() + " not found"));
158	
159	        validationService.validateCapacity(room, request.guests());
160	
161	        if (reservationRepository.hasConflictingReservation(
162	                request.roomNumber(), request.checkIn(), request.checkOut(), null)) {
163	            throw new ValidationService.ValidationException("ROOM_UNAVAILABLE",
164	                "Room is not available for the selected dates");
165	        }
166	
167	        GuestIdentification guest = createGuestIdentification(request);
168	        RatePlan ratePlan = RatePlan.valueOf(request.ratePlan());
169	
170	        PricingService.PricingResult pricing = pricingService.calculate(
171	            room, request.checkIn(), request.checkOut(), ratePlan);
172	
173	        Reservation reservation = new Reservation(
174	            null,
175	            room.number(),
176	            guest,
177	            request.checkIn(),
178	            request.checkOut(),
179	            request.guests(),
180	            ratePlan,
181	            pricing.nights,
182	            pricing.subtotal,
183	            pricing.discount,
184	            pricing.total
185	        );
186	
187	        reservationRepository.save(reservation);
188	
189	        ctx.status(201).json(toReservationResponse(reservation));
190	    }
191	
192	    private void getReservation(Context ctx) throws Exception {
193	        Long id = Long.parseLong(ctx.pathParam("id"));
194	        Reservation reservation = reservationRepository.findById(id)
195	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
196	                "Reservation " + id + " not found"));
197	
198	        ctx.json(toReservationResponse(reservation));
199	    }
200	
201	    private void confirmReservation(Context ctx) throws Exception {
202	        Long id = Long.parseLong(ctx.pathParam("id"));
203	        Reservation reservation = reservationRepository.findById(id)
204	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
205	                "Reservation " + id + " not found"));
206	
207	        reservation.confirm();
208	        reservationRepository.update(reservation);
209	
210	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
211	        Document document = documentService.generate(reservation, room);
212	        emailService.sendConfirmationEmail(
213	            reservation.getGuest().getGuestName(),
214	            reservation.getGuest().getGuestEmail(),
215	            document
216	        );
217	
218	        ctx.json(toReservationResponse(reservation));
219	    }
220	
221	    private void cancelReservation(Context ctx) throws Exception {
222	        Long id = Long.parseLong(ctx.pathParam("id"));
223	        Reservation reservation = reservationRepository.findById(id)
224	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
225	                "Reservation " + id + " not found"));
226	
227	        reservation.cancel();
228	        reservationRepository.update(reservation);
229	
230	        ctx.json(toReservationResponse(reservation));
231	    }
232	
233	    private void checkInReservation(Context ctx) throws Exception {
234	        Long id = Long.parseLong(ctx.pathParam("id"));
235	        Reservation reservation = reservationRepository.findById(id)
236	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
237	                "Reservation " + id + " not found"));
238	
239	        reservation.checkIn();
240	        reservationRepository.update(reservation);
241	
242	        ctx.json(toReservationResponse(reservation));
243	    }
244	
245	    private void checkOutReservation(Context ctx) throws Exception {
246	        Long id = Long.parseLong(ctx.pathParam("id"));
247	        Reservation reservation = reservationRepository.findById(id)
248	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
249	                "Reservation " + id + " not found"));
250	
251	        reservation.checkOut();
252	        reservationRepository.update(reservation);
253	
254	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
255	        Document document = documentService.generate(reservation, room);
256	
257	        ctx.json(toDocumentResponse(document));
258	    }
259	
260	    private void getDocument(Context ctx) throws Exception {
261	        Long id = Long.parseLong(ctx.pathParam("id"));
262	        Reservation reservation = reservationRepository.findById(id)
263	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
264	                "Reservation " + id + " not found"));
265	
266	        if (reservation.getStatus() == ReservationStatus.PENDING ||
267	            reservation.getStatus() == ReservationStatus.CANCELLED) {
268	            throw new ValidationService.ValidationException("OPERATION_NOT_ALLOWED",
269	                "Document is only available for paid reservations");
270	        }
271	
272	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
273	        Document document = documentService.generate(reservation, room);
274	
275	        ctx.json(toDocumentResponse(document));
276	    }
277	
278	    private void getMessages(Context ctx) throws Exception {
279	        List<Message> messages = messageRepository.findAll();
280	        List<Map<String, Object>> response = messages.stream()
281	            .<Map<String, Object>>map(msg -> Map.of(
282	                "id", msg.getId(),
283	                "channel", msg.getChannel(),
284	                "to", msg.getTo(),
285	                "subject", msg.getSubject(),
286	                "body", msg.getBody()
287	            ))
288	            .toList();
289	        ctx.json(response);
290	    }
291	
292	    private void getOccupancyReport(Context ctx) throws Exception {
293	        String dateParam = ctx.queryParam("date");
294	        if (dateParam == null) {
295	            throw new ValidationService.ValidationException("INVALID_REQUEST", "Date parameter is required");
296	        }
297	
298	        LocalDate date = validationService.parseDate(dateParam);
299	        List<Reservation> reservations = reservationRepository.findAll();
300	        List<Room> rooms = roomRepository.findAll();
301	
302	        String csv = reportService.generateOccupancyReport(date, reservations, rooms);
303	
304	        ctx.contentType("text/csv; charset=utf-8").result(csv);
305	    }
306	
307	    private void getRevenueReport(Context ctx) throws Exception {
308	        String monthParam = ctx.queryParam("month");
309	        if (monthParam == null) {
310	            throw new ValidationService.ValidationException("INVALID_REQUEST", "Month parameter is required");
311	        }
312	
313	        YearMonth month = validationService.parseMonth(monthParam);
314	        List<Reservation> reservations = reservationRepository.findAll();
315	
316	        String csv = reportService.generateRevenueReport(month, reservations);
317	
318	        ctx.contentType("text/csv; charset=utf-8").result(csv);
319	    }
320	
321	    private GuestIdentification createGuestIdentification(CreateReservationRequest request) {
322	        if (request.guestCpf() != null) {
323	            return new CpfGuest(request.guestName(), request.guestEmail(), request.guestCpf());
324	        } else if (request.companyCnpj() != null) {
325	            return new CompanyGuest(request.guestName(), request.guestEmail(),
326	                request.companyCnpj(), request.companyName());
327	        } else if (request.guestPassport() != null) {
328	            return new PassportGuest(request.guestName(), request.guestEmail(),
329	                request.guestPassport(), request.guestCountry());
330	        }
331	        throw new ValidationService.ValidationException("INVALID_REQUEST", "Invalid guest identification");
332	    }
333	
334	    private Map<String, Object> toReservationResponse(Reservation reservation) {
335	        Map<String, Object> response = new HashMap<>();
336	        response.put("id", reservation.getId());
337	        response.put("roomNumber", reservation.getRoomNumber());
338	        response.put("guestName", reservation.getGuest().getGuestName());
339	        response.put("guestEmail", reservation.getGuest().getGuestEmail());
340	
341	        GuestIdentification guest = reservation.getGuest();
342	        response.put("guestCpf", guest instanceof CpfGuest cpf ? cpf.guestCpf() : null);
343	        response.put("companyCnpj", guest instanceof CompanyGuest company ? company.companyCnpj() : null);
344	        response.put("companyName", guest instanceof CompanyGuest company ? company.companyName() : null);
345	        response.put("guestPassport", guest instanceof PassportGuest passport ? passport.guestPassport() : null);
346	        response.put("guestCountry", guest instanceof PassportGuest passport ? passport.guestCountry() : null);
347	
348	        response.put("checkIn", reservation.getCheckIn());
349	        response.put("checkOut", reservation.getCheckOut());
350	        response.put("guests", reservation.getGuests());
351	        response.put("ratePlan", reservation.getRatePlan().toString());
352	        response.put("nights", reservation.getNights());
353	        response.put("subtotal", reservation.getSubtotal());
354	        response.put("discount", reservation.getDiscount());
355	        response.put("total", reservation.getTotal());
356	        response.put("status", reservation.getStatus().toString());
357	        response.put("amountPaid", reservation.getAmountPaid());
358	        response.put("refund", reservation.getRefund());
359	
360	        return response;
361	    }
362	
363	    private Map<String, Object> toDocumentResponse(Document document) {
364	        Map<String, Object> response = new HashMap<>();
365	        response.put("title", getDocumentTitle(document));
366	        response.put("text", document.text());
367	        response.put("reservationId", document.reservationId());
368	        response.put("guestName", document.guestName());
369	        response.put("guestCpf", document.guestCpf());
370	        response.put("companyCnpj", document.companyCnpj());
371	        response.put("companyName", document.companyName());
372	        response.put("guestPassport", document.guestPassport());
373	        response.put("guestCountry", document.guestCountry());
374	        response.put("roomNumber", document.roomNumber());
375	        response.put("roomType", document.roomType().toString());
376	        response.put("checkIn", document.checkIn());
377	        response.put("checkOut", document.checkOut());
378	        response.put("nights", document.nights());
379	        response.put("subtotal", document.subtotal());
380	        response.put("discount", document.discount());
381	        response.put("total", document.total());
382	        return response;
383	    }
384	
385	    private String getDocumentTitle(Document document) {
386	        if (document.guestCpf() != null) {
387	            return "Comprovante de reserva";
388	        } else if (document.companyCnpj() != null) {
389	            return "Fatura de hospedagem";
390	        } else {
391	            return "Booking receipt";
392	        }
393	    }
394	}

