204	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
205	                "Reservation " + id + " not found"));
206	
207	        reservation.confirm();
208	        reservationRepository.update(reservation);
209	
210	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
211	        Document document = documentService.generate(reservation, room);
212	        emailService.sendConfirmationEmail(
213	            reservation.getGuest().getGuestName(),
214	            reservation.getGuest().getGuestEmail(),
215	            document
216	        );
217	
218	        ctx.json(toReservationResponse(reservation));
219	    }
