222	        Long id = Long.parseLong(ctx.pathParam("id"));
223	        Reservation reservation = reservationRepository.findById(id)
224	            .orElseThrow(() -> new ValidationService.ValidationException("RESERVATION_NOT_FOUND",
225	                "Reservation " + id + " not found"));
226	
227	        reservation.cancel();
228	        reservationRepository.update(reservation);
229	
230	        ctx.json(toReservationResponse(reservation));
