321	    private GuestIdentification createGuestIdentification(CreateReservationRequest request) {
322	        if (request.guestCpf() != null) {
323	            return new CpfGuest(request.guestName(), request.guestEmail(), request.guestCpf());
324	        } else if (request.companyCnpj() != null) {
325	            return new CompanyGuest(request.guestName(), request.guestEmail(),
326	                request.companyCnpj(), request.companyName());
327	        } else if (request.guestPassport() != null) {
328	            return new PassportGuest(request.guestName(), request.guestEmail(),
329	                request.guestPassport(), request.guestCountry());
330	        }
331	        throw new ValidationService.ValidationException("INVALID_REQUEST", "Invalid guest identification");
