334	    private Map<String, Object> toReservationResponse(Reservation reservation) {
335	        Map<String, Object> response = new HashMap<>();
336	        response.put("id", reservation.getId());
337	        response.put("roomNumber", reservation.getRoomNumber());
338	        response.put("guestName", reservation.getGuest().getGuestName());
339	        response.put("guestEmail", reservation.getGuest().getGuestEmail());
340	
341	        GuestIdentification guest = reservation.getGuest();
342	        response.put("guestCpf", guest instanceof CpfGuest cpf ? cpf.guestCpf() : null);
343	        response.put("companyCnpj", guest instanceof CompanyGuest company ? company.companyCnpj() : null);
344	        response.put("companyName", guest instanceof CompanyGuest company ? company.companyName() : null);
345	        response.put("guestPassport", guest instanceof PassportGuest passport ? passport.guestPassport() : null);
346	        response.put("guestCountry", guest instanceof PassportGuest passport ? passport.guestCountry() : null);
347	
348	        response.put("checkIn", reservation.getCheckIn());
349	        response.put("checkOut", reservation.getCheckOut());
350	        response.put("guests", reservation.getGuests());
351	        response.put("ratePlan", reservation.getRatePlan().toString());
352	        response.put("nights", reservation.getNights());
353	        response.put("subtotal", reservation.getSubtotal());
354	        response.put("discount", reservation.getDiscount());
355	        response.put("total", reservation.getTotal());
356	        response.put("status", reservation.getStatus().toString());
357	        response.put("amountPaid", reservation.getAmountPaid());
358	        response.put("refund", reservation.getRefund());
359	
360	        return response;
361	    }
