365	        response.put("title", getDocumentTitle(document));
366	        response.put("text", document.text());
367	        response.put("reservationId", document.reservationId());
368	        response.put("guestName", document.guestName());
369	        response.put("guestCpf", document.guestCpf());
370	        response.put("companyCnpj", document.companyCnpj());
371	        response.put("companyName", document.companyName());
372	        response.put("guestPassport", document.guestPassport());
373	        response.put("guestCountry", document.guestCountry());
374	        response.put("roomNumber", document.roomNumber());
375	        response.put("roomType", document.roomType().toString());
376	        response.put("checkIn", document.checkIn());
377	        response.put("checkOut", document.checkOut());
378	        response.put("nights", document.nights());
379	        response.put("subtotal", document.subtotal());
380	        response.put("discount", document.discount());
381	        response.put("total", document.total());
382	        return response;
383	    }
384	
385	    private String getDocumentTitle(Document document) {
386	        if (document.guestCpf() != null) {
387	            return "Comprovante de reserva";
388	        } else if (document.companyCnpj() != null) {
389	            return "Fatura de hospedagem";
390	        } else {
391	            return "Booking receipt";
392	        }
393	    }
394	}

