174	package com.marealta.domain.service;
175	
176	import com.marealta.domain.model.RatePlan;
177	import com.marealta.domain.model.Room;
178	
179	import java.math.BigDecimal;
180	import java.math.RoundingMode;
181	import java.time.LocalDate;
182	import java.time.Month;
183	
184	public class PricingService {
185	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
186	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
187	
188	    public static class PricingResult {
189	        public final int nights;
190	        public final BigDecimal subtotal;
191	        public final BigDecimal discount;
192	        public final BigDecimal total;
193	
194	        public PricingResult(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
195	            this.nights = nights;
196	            this.subtotal = subtotal;
197	            this.discount = discount;
198	            this.total = total;
199	        }
200	    }
201	
202	    public PricingResult calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
203	        int nights = calculateNights(checkIn, checkOut);
204	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut, nights);
205	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
206	        BigDecimal total = subtotal.subtract(discount);
207	
208	        return new PricingResult(nights, subtotal, discount, total);
209	    }
210	
211	    private int calculateNights(LocalDate checkIn, LocalDate checkOut) {
212	        return (int) checkIn.until(checkOut).getDays();
213	    }
214	
215	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut, int nights) {
216	        BigDecimal subtotal = BigDecimal.ZERO;
217	        LocalDate currentDate = checkIn;
218	
219	        for (int i = 0; i < nights; i++) {
220	            BigDecimal nightRate = room.nightlyRate();
221	            if (isHighSeason(currentDate)) {
222	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER)
223	                    .setScale(2, RoundingMode.HALF_EVEN);
224	            }
225	            subtotal = subtotal.add(nightRate);
226	            currentDate = currentDate.plusDays(1);
227	        }
228	
229	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
230	    }
231	
232	    private boolean isHighSeason(LocalDate date) {
233	        Month month = date.getMonth();
234	        int day = date.getDayOfMonth();
235	
236	        if (month == Month.JULY) {
237	            return true;
238	        }
239	
240	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
241	            return true;
242	        }
243	
244	        if (month == Month.DECEMBER && day >= 15) {
245	            return true;
246	        }
247	
248	        return false;
249	    }
250	
251	    private BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
252	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
253	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
254	                .setScale(2, RoundingMode.HALF_EVEN);
255	        }
256	        return BigDecimal.ZERO;
257	    }
258	}
