269	import java.util.List;
270	
271	public class ReportService {
272	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
273	
274	    public String generateOccupancyReport(LocalDate date, List<Reservation> reservations, List<Room> allRooms) {
275	        StringBuilder csv = new StringBuilder();
276	        csv.append("room,type,reservation,check_in,check_out\n");
277	
278	        List<Reservation> occupiedReservations = reservations.stream()
279	            .filter(r -> r.getStatus() != ReservationStatus.PENDING && r.getStatus() != ReservationStatus.CANCELLED)
280	            .filter(r -> !r.getCheckIn().isAfter(date) && r.getCheckOut().isAfter(date))
281	            .sorted((r1, r2) -> r1.getRoomNumber().compareTo(r2.getRoomNumber()))
282	            .toList();
283	
284	        for (Reservation reservation : occupiedReservations) {
285	            Room room = allRooms.stream()
286	                .filter(r -> r.number().equals(reservation.getRoomNumber()))
287	                .findFirst()
288	                .orElseThrow();
289	
290	            csv.append(room.number()).append(",")
291	               .append(room.type()).append(",")
292	               .append(reservation.getId()).append(",")
293	               .append(reservation.getCheckIn().format(DATE_FORMAT)).append(",")
294	               .append(reservation.getCheckOut().format(DATE_FORMAT)).append("\n");
295	        }
296	
297	        csv.append("total,").append(occupiedReservations.size())
298	           .append("/").append(allRooms.size());
299	
300	        return csv.toString();
301	    }
302	
303	    public String generateRevenueReport(YearMonth month, List<Reservation> reservations) {
304	        StringBuilder csv = new StringBuilder();
305	        csv.append("reservation,room,check_in,check_out,status,amount\n");
306	
307	        List<Reservation> relevantReservations = reservations.stream()
308	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month))
309	            .filter(r -> {
310	                BigDecimal revenue = r.getAmountPaid();
311	                if (r.getRefund() != null) {
312	                    revenue = revenue.subtract(r.getRefund());
313	                }
314	                return revenue.compareTo(BigDecimal.ZERO) > 0;
315	            })
316	            .sorted((r1, r2) -> {
317	                int dateCompare = r1.getCheckIn().compareTo(r2.getCheckIn());
318	                if (dateCompare != 0) return dateCompare;
319	                return r1.getId().compareTo(r2.getId());
320	            })
321	            .toList();
322	
323	        BigDecimal total = BigDecimal.ZERO;
324	
325	        for (Reservation reservation : relevantReservations) {
326	            BigDecimal amount = reservation.getAmountPaid();
327	            if (reservation.getRefund() != null) {
328	                amount = amount.subtract(reservation.getRefund());
329	            }
330	            total = total.add(amount);
331	
332	            csv.append(reservation.getId()).append(",")
333	               .append(reservation.getRoomNumber()).append(",")
334	               .append(reservation.getCheckIn().format(DATE_FORMAT)).append(",")
335	               .append(reservation.getCheckOut().format(DATE_FORMAT)).append(",")
336	               .append(reservation.getStatus()).append(",")
337	               .append(formatAmount(amount)).append("\n");
338	        }
339	
340	        csv.append("total,").append(formatAmount(total));
341	
342	        return csv.toString();
343	    }
344	
345	    private String formatAmount(BigDecimal amount) {
346	        return amount.toString();
347	    }
348	}

