  3	import java.sql.Connection;
  4	import java.sql.DriverManager;
  5	import java.sql.SQLException;
  6	import java.sql.Statement;
  7	
  8	public class Database {
  9	    private final Connection connection;
 10	
 11	    public Database(String url, String user, String password) throws SQLException {
 12	        this.connection = DriverManager.getConnection(url, user, password);
 13	        initializeTables();
 14	    }
 15	
 16	    public Connection getConnection() {
 17	        return connection;
 18	    }
 19	
 20	    private void initializeTables() throws SQLException {
 21	        try (Statement stmt = connection.createStatement()) {
 22	            stmt.execute("""
 23	                CREATE TABLE IF NOT EXISTS rooms (
 24	                    number VARCHAR(10) PRIMARY KEY,
 25	                    type VARCHAR(20) NOT NULL
 26	                )
 27	                """);
 28	
 29	            stmt.execute("""
 30	                CREATE TABLE IF NOT EXISTS reservations (
 31	                    id BIGSERIAL PRIMARY KEY,
 32	                    room_number VARCHAR(10) NOT NULL,
 33	                    guest_name VARCHAR(255) NOT NULL,
 34	                    guest_email VARCHAR(255) NOT NULL,
 35	                    guest_cpf VARCHAR(14),
 36	                    company_cnpj VARCHAR(18),
 37	                    company_name VARCHAR(255),
 38	                    guest_passport VARCHAR(50),
 39	                    guest_country VARCHAR(100),
 40	                    check_in DATE NOT NULL,
 41	                    check_out DATE NOT NULL,
 42	                    guests INTEGER NOT NULL,
 43	                    rate_plan VARCHAR(20) NOT NULL,
 44	                    nights INTEGER NOT NULL,
 45	                    subtotal DECIMAL(10, 2) NOT NULL,
 46	                    discount DECIMAL(10, 2) NOT NULL,
 47	                    total DECIMAL(10, 2) NOT NULL,
 48	                    status VARCHAR(20) NOT NULL,
 49	                    amount_paid DECIMAL(10, 2) NOT NULL,
 50	                    refund DECIMAL(10, 2),
 51	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
 52	                )
 53	                """);
 54	
 55	            stmt.execute("""
 56	                CREATE TABLE IF NOT EXISTS messages (
 57	                    id BIGSERIAL PRIMARY KEY,
 58	                    channel VARCHAR(20) NOT NULL,
 59	                    recipient VARCHAR(255) NOT NULL,
 60	                    subject VARCHAR(500) NOT NULL,
 61	                    body TEXT NOT NULL
 62	                )
 63	                """);
 64	        }
 65	    }
 66	
 67	    public void close() throws SQLException {
 68	        if (connection != null && !connection.isClosed()) {
 69	            connection.close();
 70	        }
 71	    }
 72	}
 73	package com.marealta.infrastructure.database;
 74	
 75	import com.marealta.domain.model.*;
 76	
 77	import java.math.BigDecimal;
 78	import java.sql.*;
 79	import java.time.LocalDate;
 80	import java.util.ArrayList;
 81	import java.util.List;
 82	import java.util.Optional;
 83	
 84	public class ReservationRepository {
 85	    private final Connection connection;
 86	
 87	    public ReservationRepository(Connection connection) {
 88	        this.connection = connection;
 89	    }
 90	
 91	    public Reservation save(Reservation reservation) throws SQLException {
 92	        String sql = """
 93	            INSERT INTO reservations (
 94	                room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
 95	                guest_passport, guest_country, check_in, check_out, guests, rate_plan,
 96	                nights, subtotal, discount, total, status, amount_paid, refund
 97	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 98	            """;
 99	
100	        try (PreparedStatement stmt = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
101	            setReservationParameters(stmt, reservation);
102	            stmt.executeUpdate();
103	
104	            try (ResultSet rs = stmt.getGeneratedKeys()) {
105	                if (rs.next()) {
106	                    reservation.setId(rs.getLong(1));
107	                }
108	            }
109	        }
110	
111	        return reservation;
112	    }
113	
114	    public void update(Reservation reservation) throws SQLException {
115	        String sql = """
116	            UPDATE reservations SET
117	                status = ?, amount_paid = ?, refund = ?
118	            WHERE id = ?
119	            """;
120	
121	        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
122	            stmt.setString(1, reservation.getStatus().name());
123	            stmt.setBigDecimal(2, reservation.getAmountPaid());
124	
125	            if (reservation.getRefund() != null) {
126	                stmt.setBigDecimal(3, reservation.getRefund());
127	            } else {
128	                stmt.setNull(3, Types.DECIMAL);
129	            }
130	
131	            stmt.setLong(4, reservation.getId());
132	            stmt.executeUpdate();
133	        }
134	    }
135	
136	    public Optional<Reservation> findById(Long id) throws SQLException {
137	        String sql = "SELECT * FROM reservations WHERE id = ?";
138	
139	        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
140	            stmt.setLong(1, id);
141	            try (ResultSet rs = stmt.executeQuery()) {
142	                if (rs.next()) {
143	                    return Optional.of(mapReservation(rs));
144	                }
145	            }
146	        }
147	
148	        return Optional.empty();
149	    }
150	
151	    public List<Reservation> findAll() throws SQLException {
152	        String sql = "SELECT * FROM reservations ORDER BY id";
153	        List<Reservation> reservations = new ArrayList<>();
154	
155	        try (PreparedStatement stmt = connection.prepareStatement(sql);
156	             ResultSet rs = stmt.executeQuery()) {
157	            while (rs.next()) {
158	                reservations.add(mapReservation(rs));
159	            }
160	        }
161	
162	        return reservations;
163	    }
164	
165	    public boolean hasConflictingReservation(String roomNumber, LocalDate checkIn, LocalDate checkOut, Long excludeId) throws SQLException {
166	        String sql = """
167	            SELECT COUNT(*) FROM reservations
168	            WHERE room_number = ?
169	            AND status != 'CANCELLED'
170	            AND check_in < ?
171	            AND check_out > ?
172	            AND (? IS NULL OR id != ?)
173	            """;
174	
175	        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
176	            stmt.setString(1, roomNumber);
177	            stmt.setDate(2, Date.valueOf(checkOut));
178	            stmt.setDate(3, Date.valueOf(checkIn));
179	            stmt.setObject(4, excludeId);
180	            stmt.setObject(5, excludeId);
181	
182	            try (ResultSet rs = stmt.executeQuery()) {
183	                if (rs.next()) {
184	                    return rs.getInt(1) > 0;
185	                }
186	            }
187	        }
188	
189	        return false;
190	    }
191	
192	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
193	        GuestIdentification guest = reservation.getGuest();
194	
195	        stmt.setString(1, reservation.getRoomNumber());
196	        stmt.setString(2, guest.getGuestName());
197	        stmt.setString(3, guest.getGuestEmail());
198	
199	        if (guest instanceof CpfGuest cpf) {
200	            stmt.setString(4, cpf.guestCpf());
201	            stmt.setNull(5, Types.VARCHAR);
202	            stmt.setNull(6, Types.VARCHAR);
203	            stmt.setNull(7, Types.VARCHAR);
204	            stmt.setNull(8, Types.VARCHAR);
205	        } else if (guest instanceof CompanyGuest company) {
206	            stmt.setNull(4, Types.VARCHAR);
207	            stmt.setString(5, company.companyCnpj());
208	            stmt.setString(6, company.companyName());
209	            stmt.setNull(7, Types.VARCHAR);
210	            stmt.setNull(8, Types.VARCHAR);
211	        } else if (guest instanceof PassportGuest passport) {
212	            stmt.setNull(4, Types.VARCHAR);
213	            stmt.setNull(5, Types.VARCHAR);
214	            stmt.setNull(6, Types.VARCHAR);
215	            stmt.setString(7, passport.guestPassport());
216	            stmt.setString(8, passport.guestCountry());
217	        }
218	
219	        stmt.setDate(9, Date.valueOf(reservation.getCheckIn()));
220	        stmt.setDate(10, Date.valueOf(reservation.getCheckOut()));
221	        stmt.setInt(11, reservation.getGuests());
222	        stmt.setString(12, reservation.getRatePlan().name());
223	        stmt.setInt(13, reservation.getNights());
224	        stmt.setBigDecimal(14, reservation.getSubtotal());
225	        stmt.setBigDecimal(15, reservation.getDiscount());
226	        stmt.setBigDecimal(16, reservation.getTotal());
227	        stmt.setString(17, reservation.getStatus().name());
228	        stmt.setBigDecimal(18, reservation.getAmountPaid());
229	
230	        if (reservation.getRefund() != null) {
231	            stmt.setBigDecimal(19, reservation.getRefund());
232	        } else {
233	            stmt.setNull(19, Types.DECIMAL);
234	        }
235	    }
236	
237	    private Reservation mapReservation(ResultSet rs) throws SQLException {
238	        GuestIdentification guest = createGuest(rs);
239	
240	        Reservation reservation = new Reservation(
241	            rs.getLong("id"),
242	            rs.getString("room_number"),
243	            guest,
244	            rs.getDate("check_in").toLocalDate(),
245	            rs.getDate("check_out").toLocalDate(),
246	            rs.getInt("guests"),
247	            RatePlan.valueOf(rs.getString("rate_plan")),
248	            rs.getInt("nights"),
249	            rs.getBigDecimal("subtotal"),
250	            rs.getBigDecimal("discount"),
251	            rs.getBigDecimal("total")
252	        );
253	
254	        String status = rs.getString("status");
255	        BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
256	        BigDecimal refund = rs.getBigDecimal("refund");
257	
258	        if (!status.equals("PENDING")) {
259	            setReservationState(reservation, status, amountPaid, refund);
260	        }
261	
262	        return reservation;
263	    }
264	
265	    private GuestIdentification createGuest(ResultSet rs) throws SQLException {
266	        String guestCpf = rs.getString("guest_cpf");
267	        String companyCnpj = rs.getString("company_cnpj");
268	        String guestPassport = rs.getString("guest_passport");
269	
270	        String guestName = rs.getString("guest_name");
271	        String guestEmail = rs.getString("guest_email");
272	
273	        if (guestCpf != null) {
274	            return new CpfGuest(guestName, guestEmail, guestCpf);
275	        } else if (companyCnpj != null) {
276	            return new CompanyGuest(guestName, guestEmail, companyCnpj, rs.getString("company_name"));
277	        } else if (guestPassport != null) {
278	            return new PassportGuest(guestName, guestEmail, guestPassport, rs.getString("guest_country"));
279	        }
280	
281	        throw new IllegalStateException("Invalid guest identification data");
282	    }
283	
284	    private void setReservationState(Reservation reservation, String status, BigDecimal amountPaid, BigDecimal refund) {
285	        try {
286	            java.lang.reflect.Field statusField = Reservation.class.getDeclaredField("status");
287	            statusField.setAccessible(true);
288	            statusField.set(reservation, ReservationStatus.valueOf(status));
289	
290	            java.lang.reflect.Field amountPaidField = Reservation.class.getDeclaredField("amountPaid");
291	            amountPaidField.setAccessible(true);
292	            amountPaidField.set(reservation, amountPaid);
293	
294	            if (refund != null) {
295	                java.lang.reflect.Field refundField = Reservation.class.getDeclaredField("refund");
296	                refundField.setAccessible(true);
297	                refundField.set(reservation, refund);
298	            }
299	        } catch (Exception e) {
300	            throw new RuntimeException("Failed to set reservation state", e);
301	        }
302	    }
303	}
