136	    public Optional<Reservation> findById(Long id) throws SQLException {
137	        String sql = "SELECT * FROM reservations WHERE id = ?";
138	
139	        try (PreparedStatement stmt = connection.prepareStatement(sql)) {
140	            stmt.setLong(1, id);
141	            try (ResultSet rs = stmt.executeQuery()) {
142	                if (rs.next()) {
143	                    return Optional.of(mapReservation(rs));
144	                }
145	            }
146	        }
147	
148	        return Optional.empty();
149	    }
