 53	        boolean hasCpf = request.guestCpf() != null;
 54	        boolean hasCompany = request.companyCnpj() != null && request.companyName() != null;
 55	        boolean hasPassport = request.guestPassport() != null && request.guestCountry() != null;
 56	
 57	        int count = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
